auto countInversions(auto arr) {
  auto mergeSort(auto temp, auto left, auto right) {
    if (left >= right) return 0;
    const auto mid = ((left + right) / 2);
    auto invCount = 0;
    invCount += mergeSort(temp, left, mid);
    invCount += mergeSort(temp, mid + 1, right);
    invCount += merge(temp, left, mid, right);
    return invCount;
  }
  auto merge(auto temp, auto left, auto mid, auto right) {
    auto i = left, j = mid + 1, k = left, inv = 0;
    while (i <= mid && j <= right) {
      if (arr[i] <= arr[j]) {
        temp[k++] = arr[i++];
      } else {
        temp[k++] = arr[j++];
        inv += (mid - i + 1);
      }
    }
    while (i <= mid) temp[k++] = arr[i++];
    while (j <= right) temp[k++] = arr[j++];
    for (auto x = left; x <= right; x++) arr[x] = temp[x];
    return inv;
  }
  return mergeSort(new Array(arr.size()), 0, arr.size() - 1);
}

