class MinHeap {
private:
    vector<int> heap;
    void up(int i) {
        while (i > 0) {
            int p = (i - 1) / 2;
            if (heap[p] <= heap[i]) break;
            swap(heap[p], heap[i]);
            i = p;
        }
    }
    void down(int i) {
        int len = heap.size();
        while (2 * i + 1 < len) {
            int child = 2 * i + 1;
            if (child + 1 < len && heap[child + 1] < heap[child]) child++;
            if (heap[i] <= heap[child]) break;
            swap(heap[i], heap[child]);
            i = child;
        }
    }
public:
    void push(int val) {
        heap.push_back(val); up(heap.size() - 1);
    }
    int pop() {
        if (heap.empty()) return -1;
        int minVal = heap[0];
        heap[0] = heap.back(); heap.pop_back();
        if (!heap.empty()) down(0);
        return minVal;
    }
};

