class ArrayStack {
private:
    int* arr;
    int topIdx;
    int capacity;
public:
    ArrayStack(int size) {
        capacity = size;
        arr = new int[capacity];
        topIdx = -1;
    }
    void push(int x) {
        if (topIdx >= capacity - 1) return; // overflow
        arr[++topIdx] = x;
    }
    int pop() {
        if (topIdx < 0) return -1; // underflow
        return arr[topIdx--];
    }
    int top() {
        if (topIdx < 0) return -1;
        return arr[topIdx];
    }
    bool isEmpty() { return topIdx == -1; }
};

