class LRUCache {
  constructor(capacity) {
    this.capacity = capacity; this.map = unordered_map<int, int>();
    this.head = { prev: nullptr, next: nullptr };
    this.tail = { prev: nullptr, next: nullptr };
    this.head->next = this.tail; this.tail.prev = this.head;
  }
  remove(node) {
    node.prev->next = node->next; node->next.prev = node.prev;
  }
  insert(node) {
    node->next = this.head->next; node->next.prev = node;
    this.head->next = node; node.prev = this.head;
  }
  get(key) {
    if (this.map.has(key)) {
      const auto node = this.map.get(key); this.remove(node); this.insert(node);
      return node->val;
    }
    return -1;
  }
  put(key, value) {
    if (this.map.has(key)) this.remove(this.map.get(key));
    const auto newNode = { key, val: value, prev: nullptr, next: nullptr };
    this.insert(newNode); this.map.set(key, newNode);
    if (this.map.size > this.capacity) {
      const auto lru = this.tail.prev; this.remove(lru); this.map.delete(lru.key);
    }
  }
}

