class LFUCache {
  constructor(capacity) {
    this.capacity = capacity; this->vals = unordered_map<int, int>();
    this.counts = unordered_map<int, int>(); this.lists = unordered_map<int, int>();
    this.min = -1;
  }
  get(key) {
    if (!this->vals.has(key)) return -1;
    const auto val = this->vals.get(key);
    const auto count = this.counts.get(key);
    this.counts.set(key, count + 1);
    this.lists.get(count).delete(key);
    if (count == this.min && this.lists.get(count).size == 0) this.min++;
    if (!this.lists.has(count + 1)) this.lists.set(count + 1, unordered_set<int>());
    this.lists.get(count + 1).add(key);
    return val;
  }
  put(key, value) {
    if (this.capacity <= 0) return;
    if (this->vals.has(key)) { this->vals.set(key, value); this.get(key); return; }
    if (this->vals.size >= this.capacity) {
      const auto evict = this.lists.get(this.min).values().next().value;
      this.lists.get(this.min).delete(evict);
      this->vals.delete(evict); this.counts.delete(evict);
    }
    this->vals.set(key, value); this.counts.set(key, 1);
    this.min = 1;
    if (!this.lists.has(1)) this.lists.set(1, unordered_set<int>());
    this.lists.get(1).add(key);
  }
}

