#include <unordered_map>
#include <list>
class LFUCache {
private:
    struct Node {
        int key, val, freq;
        Node(int k, int v, int f) : key(k), val(v), freq(f) {}
    };
    int cap, minFreq;
    std::unordered_map<int, std::list<Node>::iterator> keyToIter;
    std::unordered_map<int, std::list<Node>> freqToList;
    void updateFreq(int key) {
        auto iter = keyToIter[key];
        int f = iter->freq;
        int val = iter->val;
        freqToList[f].erase(iter);
        if (freqToList[f].empty() && f == minFreq) {
            minFreq++;
        }
        freqToList[f + 1].push_front(Node(key, val, f + 1));
        keyToIter[key] = freqToList[f + 1].begin();
    }
public:

    LFUCache(int capacity) : cap(capacity), minFreq(0) {}
    int get(int key) {
        if (keyToIter.find(key) == keyToIter.end()) return -1;
        updateFreq(key);
        return keyToIter[key]->val;
    }
    void put(int key, int value) {
        if (cap <= 0) return;
        if (keyToIter.find(key) != keyToIter.end()) {
            keyToIter[key]->val = value;
            updateFreq(key);
            return;
        }
        if (keyToIter.size() >= cap) {
            auto& list = freqToList[minFreq];
            keyToIter.erase(list.back().key);
            list.pop_back();
        }
        minFreq = 1;
        freqToList[1].push_front(Node(key, value, 1));
        keyToIter[key] = freqToList[1].begin();
    }
};

