auto largestRectangleArea(auto heights) {
  const auto stack = [];
  auto maxArea = 0, i = 0;
  while (i < heights.size()) {
    if (stack.size() == 0 || heights[stack[stack.size() - 1]] <= heights[i]) {
      stack.push(i++);
    } else {
      const auto tp = stack.pop();
      const auto area = heights[tp] * (stack.size() == 0 ? i : i - stack[stack.size() - 1] - 1);
      maxArea = max(maxArea, area);
    }
  }
  while (stack.size() > 0) {
    const auto tp = stack.pop();
    const auto area = heights[tp] * (stack.size() == 0 ? i : i - stack[stack.size() - 1] - 1);
    maxArea = max(maxArea, area);
  }
  return maxArea;
}

