  auto fresh = 0;
  for (auto i = 0; i < r; i++) {
    for (auto j = 0; j < c; j++) {
      if (grid[i][j] == 2) q.push([i, j, 0]);
      else if (grid[i][j] == 1) fresh++;
    }
  }
  auto mins = 0;
  while (q.size() > 0) {
    const auto [x, y, t] = q.shift(); mins = t;
    const auto dirs = [[0,1], [0,-1], [1,0], [-1,0]];
    for (const auto [dx, dy] of dirs) {
