      if (!curr.children[char]) curr.children[char] = new TrieNodeAllPrefix();
      curr = curr.children[char];
    }
    curr.isEnd = true;
  }
  auto longest = "";
  for (const auto w of words) {
    auto curr = root, possible = true;
    for (const auto char of w) {
