auto powerSet(auto s) {
  const auto result = [];
  auto backtrack(auto index, auto path) {
    if (index == s.size()) {
      result.push(path); return;
    }
    backtrack(index + 1, path + s[index]); // include
    backtrack(index + 1, path);            // exclude
  }
  backtrack(0, "");
  return result.sort();
}

