class Solution {
    void backtrack(string& s, int i, string path, vector<string>& res) {
        if (i == s.size()) {
            res.push_back(path);
            return;
        }
        backtrack(s, i + 1, path + s[i], res); // Pick
        backtrack(s, i + 1, path, res);        // Skip
    }
public:
    vector<string> powerSet(string s) {
        vector<string> res;
        backtrack(s, 0, "", res);
        return res;
    }
};

