class TrieNodeBit {
  constructor() { this.children = {}; } // holds '0' and '1'
}
class BitTrie {
  constructor() { this.root = new TrieNodeBit(); }
  insert(num) {
    auto curr = this.root;
    for (auto i = 31; i >= 0; i--) {
      const auto bit = (num >> i) & 1;
      if (!curr.children[bit]) curr.children[bit] = new TrieNodeBit();
      curr = curr.children[bit];
    }
  }
  getMaxXOR(num) {
    auto curr = this.root, maxXOR = 0;
    for (auto i = 31; i >= 0; i--) {
      const auto bit = (num >> i) & 1;
      const auto opposite = 1 - bit;
      if (curr.children[opposite]) {
        maxXOR = maxXOR | (1 << i);
        curr = curr.children[opposite];
      } else {
        curr = curr.children[bit];
      }
    }
    return maxXOR;
  }
}
auto findMaximumXOR(auto nums) {
  const auto trie = new BitTrie();
  for (const auto n of nums) trie.insert(n);
  auto maxVal = 0;
  for (const auto n of nums) {
    maxVal = max(maxVal, trie.getMaxXOR(n));
  }
  return maxVal;
}

