  nums.sort((a, b) => a - b);
  const auto qWithIdx = queries.map((q, idx) => ({ x: q[0], m: q[1], idx }));
  qWithIdx.sort((a, b) => a.m - b.m);
  const auto trie = new BitTrie2();
