    sort(nums.begin(), nums.end());
    int qSize = queries.size();
    vector<vector<int>> q(qSize, vector<int>(3));
    for (int i = 0; i < qSize; i++) {
        q[i] = {queries[i][1], queries[i][0], i};
    }
    sort(q.begin(), q.end());
    vector<int> ans(qSize);
    Trie trie;
    int idx = 0, n = nums.size();
    for (auto& query : q) {
        int m = query[0], x = query[1], originalIdx = query[2];
        while (idx < n && nums[idx] <= m) {
            trie.insert(nums[idx++]);
        }
        ans[originalIdx] = trie.getMaxXOR(x);
    }
    return ans;
