  auto solve(auto left, auto right) {
    if (left > right) return nullptr;
    const auto mid = (left + right) >> 1;
    const auto node = new TreeNode(nums[mid]);
    node.left = solve(left, mid - 1);
    node.right = solve(mid + 1, right);
    return node;
  }
  return solve(0, nums.size() - 1);
