auto findPreSuc(auto root, auto key) {
  auto predecessor = nullptr, successor = nullptr;
  auto curr = root;
  while (curr) {
    if (curr->val >= key) {
      curr = curr.left;
    } else {
      predecessor = curr; curr = curr.right;
    }
  }
  curr = root;
  while (curr) {
    if (curr->val <= key) {
      curr = curr.right;
    } else {
      successor = curr; curr = curr.left;
    }
  }
  return { predecessor, successor };
}

