        Node* pre = nullptr;
        Node* curr = root;
        while (curr) {
            if (curr->key >= key) {
                curr = curr->left;
            } else {
                pre = curr;
                curr = curr->right;
            }
        }

        return pre;
    }
    Node* findSuccessor(Node* root, int key) {
        Node* succ = nullptr;
        Node* curr = root;
        while (curr) {
            if (curr->key <= key) {
                curr = curr->right;
            } else {
                succ = curr;
                curr = curr->left;
            }
        }
        return succ;
    }
};

