class BSTIteratorDirectional {
  constructor(root, isReverse) {
    this.stack = []; this.isReverse = isReverse; this.pushAll(root);
  }
  next() {
    const auto node = this.stack.pop();
    if (!this.isReverse) this.pushAll(node.right);
    else this.pushAll(node.left);
    return node->val;
  }
  pushAll(node) {
    auto curr = node;
    while (curr) {
      this.stack.push(curr);
      curr = !this.isReverse ? curr.left : curr.right;
    }
  }
}
auto findTarget(auto root, auto k) {
  if (!root) return false;
  const auto l = new BSTIteratorDirectional(root, false);
  const auto r = new BSTIteratorDirectional(root, true);
  auto left = l->next(), right = r->next();
  while (left < right) {
    const auto sum = left + right;
    if (sum == k) return true;
    if (sum < k) left = l->next();
    else right = r->next();
  }
  return false;
}

