class BSTIterator {
    stack<TreeNode*> s;
    bool isReverse;
    void pushAll(TreeNode* node) {
        while (node) {
            s.push(node);
            node = !isReverse ? node->left : node->right;
        }
    }
public:
    BSTIterator(TreeNode* root, bool isRev) : isReverse(isRev) {
        pushAll(root);
    }
    int next() {
        TreeNode* temp = s.top(); s.pop();
        if (!isReverse)
            pushAll(temp->right);
        else
            pushAll(temp->left);
        return temp->val;
    }

    bool hasNext() {
        return !s.empty();
    }
};
class Solution {
public:
    bool findTarget(TreeNode* root, int k) {
        if (!root) return false;
        BSTIterator l(root, false);
        BSTIterator r(root, true);
        int left = l.next();
        int right = r.next();
        while (left < right) {
            if (left + right == k) return true;
            if (left + right < k) left = l.next();
            else right = r.next();
        }
        return false;
    }
};

