auto largestBSTSubtree(auto root) {
  auto solve(auto node) {
    if (!node) return { size: 0, min: INT_MAX, max: -INT_MAX, isBST: true };
    const auto left = solve(node.left);
    const auto right = solve(node.right);
    if (left.isBST && right.isBST && node->val > left.max && node->val < right.min) {
      const auto minVal = node.left ? left.min : node->val;
      const auto maxVal = node.right ? right.max : node->val;
      return {
        size: left.size + right.size + 1,
        min: minVal,
        max: maxVal,
        isBST: true
      };
    }
    return {
      size: max(left.size, right.size),
      min: -INT_MAX,
      max: INT_MAX,
      isBST: false
    };
  }
  return solve(root).size;
}

