auto serialize(auto root) {
  if (!root) return "nullptr";
  const auto res = [];
  const auto q = [root];
  while (q.size() > 0) {
    const auto node = q.shift();
    if (node) {
      res.push(node->val);
      q.push(node.left); q.push(node.right);
    } else {
      res.push("nullptr");
    }
  }
  return res.join(",");
}
auto deserialize(auto data) {
  if (data == "nullptr") return nullptr;
  const auto vals = data.split(",");
  const auto root = new TreeNode(parseInt(vals[0]));
  const auto q = [root];
  auto i = 1;
  while (q.size() > 0 && i < vals.size()) {
    const auto node = q.shift();
    if (vals[i] != "nullptr") {
      node.left = new TreeNode(parseInt(vals[i]));
      q.push(node.left);
    }
    i++;
    if (i < vals.size() && vals[i] != "nullptr") {
      node.right = new TreeNode(parseInt(vals[i]));
      q.push(node.right);
    }
    i++;
  }
  return root;
}

