class Codec {
public:
    string serialize(TreeNode* root) {
        if (!root) return "";
        string s = "";
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            TreeNode* curr = q.front(); q.pop();
            if (curr) {
                s.append(to_string(curr->val) + ",");
                q.push(curr->left);
                q.push(curr->right);
            } else {
                s.append("#,");
            }
        }
        return s;
    }
