        if (data.empty()) return nullptr;
        stringstream s(data);

        string str;
        getline(s, str, ',');
        TreeNode* root = new TreeNode(stoi(str));
        queue<TreeNode*> q;
        q.push(root);
        while (!q.empty()) {
            TreeNode* curr = q.front(); q.pop();
            getline(s, str, ',');
            if (str != "#") {
                curr->left = new TreeNode(stoi(str));
                q.push(curr->left);
            }
            getline(s, str, ',');
            if (str != "#") {
                curr->right = new TreeNode(stoi(str));
                q.push(curr->right);
            }
        }
        return root;
    }
};

