int findSet(int i, vector<int>& parent) {
    if (parent[i] == i) return i;
    return parent[i] = findSet(parent[i], parent); // Path compression
}

bool unionSets(int i, int j, vector<int>& parent, vector<int>& rank) {
    int rootI = findSet(i, parent), rootJ = findSet(j, parent);
    if (rootI == rootJ) return false;

    if (rank[rootI] < rank[rootJ]) parent[rootI] = rootJ;
    else if (rank[rootI] > rank[rootJ]) parent[rootJ] = rootI;
    else { parent[rootJ] = rootI; rank[rootI]++; }
    return true;
}

int buildMST(vector<Edge>& edges, vector<int>& parent, vector<int>& rank) {
    int mstWeight = 0, count = 0;
    for (auto& edge : edges) {
        if (unionSets(edge.u, edge.v, parent, rank)) {
            mstWeight += edge.w;
            if (++count == parent.size() - 1) break;
        }
    }
    return mstWeight;
}

