int longestCommonSubsequence(string t1, string t2) {
    vector<int> dp(t2.size() + 1, 0);
    for (int i = 1; i <= t1.size(); ++i) {
        int prev = 0;
        for (int j = 1; j <= t2.size(); ++j) {
            int temp = dp[j];
            dp[j] = (t1[i-1] == t2[j-1]) ? prev + 1 : max(dp[j], dp[j-1]);
            prev = temp;
        }
    }
    return dp[t2.size()];
}

