int superEggDrop(int K, int N) {
    vector<int> dp(K + 1, 0);
    int attempts = 0;
    while (dp[K] < N) {
        attempts++;
        for (int j = K; j >= 1; j--) {
            dp[j] = dp[j] + dp[j - 1] + 1;
        }
    }
    return attempts;
}

